// EXPERIMENTAL BLE restore: the Swift port must build the same frames as ble/fuji_ble/restore_profile.py (golden
// vectors in Fixtures/restore-profile-vectors.json, generated by the Python code) and run the same conversation
// against a fake camera that speaks a given protocol.
import Foundation
import Testing
@testable import DialInCamera

/// A camera that speaks `profile`'s restore protocol: request → ready, frames (acked in ack pacing), last frame →
/// completion (or 04 on a bad file), finish → applied.
actor RestoreFakeGATT: GATTClient {
    let profile: FujiBLEFlows.RestoreProfile
    var refuse: String?
    private(set) var writes: [(String, Data)] = []
    private(set) var received = Data()
    private(set) var applied = false
    private var queued: [String: [Data]] = [:]
    private var armed = false
    private var nextSeq = 0
    private var frames = 0

    init(profile: FujiBLEFlows.RestoreProfile, refuse: String? = nil) {
        self.profile = profile
        self.refuse = refuse
    }

    func has(_ c: String) async -> Bool { true }
    func read(_ c: String) async throws -> Data { Data() }
    func subscribe(_ c: String) async -> Bool { true }
    func drain(_ c: String) async -> [Data] { queued.removeValue(forKey: c) ?? [] }
    var isLinkUp: Bool { true }

    func nextValue(_ c: String, timeout: Duration) async -> Data? {
        guard var q = queued[c], !q.isEmpty else { return nil }
        let v = q.removeFirst()
        queued[c] = q
        return v
    }

    private func push(_ c: String?, _ v: Data) {
        guard let c else { return }
        queued[c, default: []].append(v)
    }

    private func pad(_ hex: String?, _ fallback: [UInt8], _ n: Int) -> Data {
        var d = hex.flatMap(Data.init(hexString:)) ?? Data(fallback)
        if d.count < n { d += Data(count: n - d.count) }
        return d
    }

    func write(_ c: String, _ value: Data) async throws {
        writes.append((c, value))
        let p = profile
        if c == p.requestChar, value == Data(hexString: p.requestValue ?? "") {
            armed = true
            nextSeq = p.seqStart
            received = Data()
            push(p.readyChar, pad(p.readyValuePrefix, [1], 2))
            return
        }
        guard armed else { return }
        if c == FujiBLE.filePartialData {
            let ch = try FileChunk.parse(value)
            let last = p.lastSeq.map { Int(ch.seq) == $0 } ?? false
            if !last {
                #expect(Int(ch.seq) == nextSeq)
                nextSeq += 1
                frames += 1
                received += ch.payload
                if p.pacing == "ack" { push(p.ackChar, Data([2, 0, UInt8(frames & 0xFF), 0])) }
                return
            }
            var body = ch.payload
            if p.trailerSum {
                let tail = [UInt8](body.suffix(2))
                body = body.prefix(body.count - 2)
                #expect(Int(tail[0]) | Int(tail[1]) << 8 == byteSum16(received + body))
            }
            received += body
            push(p.completeChar, refuse == nil ? pad(p.completeValuePrefix, [3, 0], 4) : Data([4, 0, 0, 0]))
            return
        }
        if c == p.finishChar, value == Data(hexString: p.finishValue ?? ""), refuse == nil {
            applied = true
            armed = false
        }
    }
}

struct RestoreVectors: Decodable {
    struct Entry: Decodable {
        var name: String
        var frames_hex: [String]
        var setup: [[String]]
    }
    var data_hex: String
    var profiles: [Entry]
}

@Suite("BLE restore (experimental)")
struct BLERestoreTests {
    static func vectors() throws -> (RestoreVectors, [FujiBLEFlows.RestoreProfile]) {
        let raw = try Fixture.data("restore-profile-vectors.json")
        let v = try JSONDecoder().decode(RestoreVectors.self, from: raw)
        let obj = try JSONSerialization.jsonObject(with: raw) as! [String: Any]
        let profiles = try (obj["profiles"] as! [[String: Any]]).map {
            try FujiBLEFlows.RestoreProfile.decode(JSONSerialization.data(withJSONObject: $0["profile"]!))
        }
        return (v, profiles)
    }

    @Test("Frames and setup writes match the Python profiles byte for byte")
    func goldenVectors() throws {
        let (v, profiles) = try Self.vectors()
        let data = try #require(Data(hexString: v.data_hex))
        #expect(profiles.count == 3)
        for (entry, p) in zip(v.profiles, profiles) {
            #expect(p.frames(data).map(\.hexString) == entry.frames_hex, "\(entry.name)")
            #expect(p.setupWrites(data).map { [$0.0, $0.1.hexString] } == entry.setup, "\(entry.name)")
        }
        #expect(profiles[0].hasRequest == false, "the default profile can't send anything")
        #expect(profiles[1].captured && profiles[1].seqStart == 1 && profiles[1].pacing == "ack")
        #expect(profiles[2].finishChar == nil && profiles[2].lastSeq == nil, "JSON nulls stay nil")
    }

    @Test("Profile JSON round-trips through Swift, and junk is refused")
    func jsonRoundTrip() throws {
        let (_, profiles) = try Self.vectors()
        for p in profiles {
            let again = try FujiBLEFlows.RestoreProfile.decode(JSONEncoder().encode(p))
            #expect(again == p)
        }
        #expect(throws: (any Error).self) { try FujiBLEFlows.RestoreProfile.decode(Data(#"{"format":"other/2"}"#.utf8)) }
        #expect(throws: (any Error).self) { try FujiBLEFlows.RestoreProfile.decode(Data(#"{"pacing":"sometimes"}"#.utf8)) }
    }

    @Test("A captured-style profile uploads the file and the camera applies it")
    func restoreLands() async throws {
        let (_, profiles) = try Self.vectors()
        var p = profiles[1]
        p.setup = [.init(op: "file_information", name: "backup.dat"), .init(op: "write_u32", char: FujiBLE.filePartialSize, value: 200)]
        let file = Data((0..<5000).map { UInt8(truncatingIfNeeded: $0 &* 7) })
        let cam = RestoreFakeGATT(profile: p)
        let result = try await FujiBLEFlows.restoreSettings(cam, file: file, profile: p, firstAckWait: .milliseconds(10))
        #expect(await cam.applied)
        #expect(await cam.received == file)
        #expect(result.finalState == Data([3, 0, 0, 0]))
        #expect(result.framesSent == p.frames(file).count)
        let writes = await cam.writes
        #expect(writes.first?.0 == p.requestChar)
        #expect(writes.last?.0 == FujiBLE.fileTransferResult && writes.last?.1 == Data([3, 0]))
    }

    @Test("Fixed pacing, finish before completion, write-without-response frames")
    func fixedPacing() async throws {
        var p = FujiBLEFlows.RestoreProfile()
        p.requestChar = FujiBLE.restoreRequestCandidates[0]
        p.requestValue = "0100"
        p.readyChar = FujiBLE.backupState
        p.pacing = "fixed"
        p.gapMs = 0
        p.frameWithResponse = false
        p.finishAfterComplete = false
        let file = Data(repeating: 0x5A, count: 777)
        let cam = RestoreFakeGATT(profile: p)
        let result = try await FujiBLEFlows.restoreSettings(cam, file: file, profile: p)
        #expect(await cam.received == file)
        #expect(await cam.applied)
        #expect(result.finalState?.first == 3)
    }

    @Test("Wrong request: the camera never says ready and nothing is uploaded")
    func wrongRequest() async throws {
        let (_, profiles) = try Self.vectors()
        var guess = profiles[1]
        guess.requestValue = "0100"
        guess.readyTimeout = 0.05
        let cam = RestoreFakeGATT(profile: profiles[1])
        await #expect(throws: FujiBLEError.self) {
            _ = try await FujiBLEFlows.restoreSettings(cam, file: Data(count: 300), profile: guess)
        }
        #expect(await cam.writes.allSatisfy { $0.0 != FujiBLE.filePartialData })
    }

    @Test("A camera that refuses the file is reported, not applied")
    func refused() async throws {
        let (_, profiles) = try Self.vectors()
        let cam = RestoreFakeGATT(profile: profiles[1], refuse: "bad checksum")
        do {
            _ = try await FujiBLEFlows.restoreSettings(cam, file: Data(count: 900), profile: profiles[1], firstAckWait: .milliseconds(10))
            Issue.record("expected a refusal")
        } catch let e as FujiBLEError {
            #expect(e.description.contains("refused the file"))
        }
        #expect(await !cam.applied)
    }

    @Test("Without a request or the experimental opt-in, restore stays unsupported")
    func gated() async throws {
        let link = FujiBluetoothLink()
        await #expect(throws: FujiBLEFlows.restoreUnsupported) { try await link.restoreSettings(Data()) }
        let (_, profiles) = try Self.vectors()
        await #expect(throws: FujiBLEFlows.restoreUnsupported) { try await link.restoreSettings(Data(), profile: profiles[1]) }
        await #expect(throws: FujiBLEFlows.restoreUnsupported) {
            try await link.restoreSettings(Data(), profile: profiles[0], experimental: true)
        }
        await #expect(throws: FujiBLEFlows.restoreUnsupported) {
            _ = try await FujiBLEFlows.restoreSettings(RestoreFakeGATT(profile: profiles[0]), file: Data(), profile: profiles[0])
        }
    }

    @Test("Slot names are read from an X100VI-shaped settings file (records = last seven 0x400 blocks, name +0x1E5)")
    func settingsFileNames() {
        var d = [UInt8](repeating: 0, count: 70_524)
        d.replaceSubrange(0..<16, with: Array("FUJIFILMX-BACKUP".utf8))
        d.replaceSubrange(0x10..<0x14, with: Array("0100".utf8))
        d.replaceSubrange(0x14..<0x1A, with: Array("X100VI".utf8))
        d.replaceSubrange(0x98..<0x9C, with: [0xA8, 0, 0, 0])
        let len = 70_524 - 0xA8
        d.replaceSubrange(0xA0..<0xA4, with: [UInt8(len & 0xFF), UInt8(len >> 8 & 0xFF), UInt8(len >> 16 & 0xFF), 0])
        for k in 0..<7 {
            let name = Array("Look \(k + 1)".utf8)
            let a = 0xF800 + k * 0x400 + 0x1E5
            d.replaceSubrange(a..<(a + name.count), with: name)
        }
        let names = SettingsFileNames.read(Data(d))
        #expect(names == (1...7).map { "Look \($0)" })
        #expect(SettingsFileNames.read(Data(count: 100)).isEmpty)
    }
}
